#include <iostream>

int main() {
    int grade{0};
    if (std::cin >> grade) {
        // Single-selection if: performs action only if condition is true
        if (grade >= 60) {
            std::cout << "Passed\n";
        }
    }
    return 0;
}

#include <iostream>

int main() {
    int grade{0};
    if (std::cin >> grade) {
        // Demonstration of ternary conditional operator
        std::cout << ((grade >= 60) ? "Passed" : "Failed") << '\n';

        // Nested if...else multi-way branching
        if (grade >= 90) {
            std::cout << "A\n";
        } else {
            if (grade >= 80) {
                std::cout << "B\n";
            } else {
                if (grade >= 70) {
                    std::cout << "C\n";
                } else {
                    if (grade >= 60) {
                        std::cout << "D\n";
                    } else {
                        std::cout << "F\n";
                    }
                }
            }
        }
    }
    return 0;
}
